COMMENT ON COLUMN "public"."sys_oss_config"."ext1" IS '扩展字段';
COMMENT ON COLUMN "public"."sys_oss_config"."create_dept" IS '创建部门';
COMMENT ON COLUMN "public"."sys_oss_config"."create_by" IS '创建者';
